using System; using System.Collections.Generic; using System.Linq;
using System.Text.Json; using System.Threading; using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class Res { public int k { get; set; } public double v { get; set; } }

public class Sub : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int k = int.Parse(input.Parameters["k"]);
        double a = 8.0 * k / 32.0, b = 8.0 * (k + 1) / 32.0;
        int n = 10000;
        double h = (b - a) / n;
        double s = 0.0;
        for (int i = 0; i <= n; i++)
        {
            double x = a + i * h;
            double fx = Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2.0 * x));
            double w = (i == 0 || i == n) ? 1.0 : ((i % 2 == 1) ? 4.0 : 2.0);
            s += w * fx;
        }
        double val = s * h / 3.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Res { k = k, v = val })));
    }
}

